 {tab === 'reports' && <><div className="toolbar"><h2>{tr("My reports")}</h2><div className="report-actions"><button className="button secondary" onClick={() => report('lost')}>{tr("I lost something")}</button><button className="button primary" onClick={() => report('found')}>{tr("I found something")}</button></div></div>{dashboard.reports.length ? <div className="manage-list">{dashboard.reports.map((r: Item) => <article key={r.id}><Picture item={r}/><div><Badge type={r.type}>{r.type}</Badge><h3>{r.title}</h3><p>{r.status}{r.hidden ? ' · Hidden by moderation' : ''}</p></div><div className="row-actions"><button className="text-button" onClick={() => openReport(r.id)}>{tr("View")}</button>{['Open', 'Claim Pending'].includes(r.status) && <><button className="text-button" onClick={() => { setError(''); setForm(r); }}>{tr("Edit")}</button><button className="text-button" onClick={() => perform(async () => { await api('reports/' + r.id, { action: 'close' }, 'PATCH'); await refreshDashboard(); refreshStats(); tell('Report closed.'); })}>{tr("Close")}</button></>}{['Open', 'Claim Pending', 'Closed', 'Returned'].includes(r.status) && <button className="text-button danger" aria-label={'Delete ' + r.title} onClick={() => {setError('');setDeleteFor(r);}}><Trash2 size={18}/> {tr("Delete report")}</button>}</div></article>)}</div> : <Empty title="Let’s start with your first report" detail="Lost or found something? Share a few details and we’ll look for possible connections."/>}</>}
