 {tab === 'claims' && (dashboard.claims.length ? <div className="manage-list">{dashboard.claims.map((c: Item) => <article key={c.id}><span className="claim-icon"><MessageCircle /></span><div><Badge>{c.status}</Badge><h3>{c.title}</h3><p>{c.owner === user.id ? 'You are the finder' : 'Your ownership claim'} · {date(c.created)}</p></div><button className="button secondary" onClick={() => openClaim(c.id)}>{tr("Open conversation")}<ArrowUpRight size={16}/></button></article>)}</div> : <Empty title="Connections start with a claim" detail="Find a report that looks like your item, then share private ownership evidence with its finder."/>)}
